//! The editor as a Kotlin class, generated by BoltFFI.
//!
//! Everything except the surface and accessibility (which need JNI objects,
//! see `shell.rs`) goes through here. Structured values cross as JSON
//! strings; coordinates are in pixels. All calls happen on the UI thread
//! (Skia objects are not thread-safe), hence `single_threaded`.

use openrich_commands::{KeyEvent, KeyPlatform, Modifiers};
use openrich_extensions::{Editor, EditorOptions};
use openrich_model::fragment_to_json;
use openrich_theme::Theme;
use openrich_view::{EditorView, Effect, HapticKind, Insets, MenuItem, TouchPhase, ViewOptions};
use serde_json::{Map, Value, json};

pub struct NativeEditor {
    pub(crate) view: EditorView,
    /// The drawing surface and accessibility (`shell.rs`).
    #[cfg(target_os = "android")]
    pub(crate) shell: crate::shell::Shell,
}

impl std::fmt::Debug for NativeEditor {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NativeEditor")
            .field("view", &self.view)
            .finish()
    }
}

fn theme(dark: bool) -> Theme {
    if dark { Theme::dark() } else { Theme::light() }
}

fn menu_item_name(item: MenuItem) -> &'static str {
    match item {
        MenuItem::Cut => "cut",
        MenuItem::Copy => "copy",
        MenuItem::Paste => "paste",
        MenuItem::SelectAll => "selectAll",
    }
}

/// `[{"name": "toggleBold", "args": …}, …]` as chain steps.
fn steps(json: &str) -> Option<Vec<(String, Value)>> {
    let Value::Array(items) = serde_json::from_str(json).ok()? else {
        return None;
    };
    items
        .into_iter()
        .map(|item| {
            let name = item.get("name")?.as_str()?.to_string();
            let args = item.get("args").cloned().unwrap_or(Value::Null);
            Some((name, args))
        })
        .collect()
}

/// A document for `content`: Tiptap JSON, or else HTML.
fn initial_doc(content: &str) -> Option<Value> {
    let content = content.trim();
    if content.is_empty() {
        return None;
    }
    if let Ok(json) = serde_json::from_str(content) {
        return Some(json);
    }
    let schema = Editor::new(EditorOptions::default()).ok()?.schema().clone();
    let fragment = openrich_markup::parse_fragment(&schema, content);
    (fragment.child_count() > 0)
        .then(|| json!({"type": "doc", "content": fragment_to_json(&fragment)}))
}

fn args(json: &str) -> Value {
    serde_json::from_str(json).unwrap_or(Value::Null)
}

impl NativeEditor {
    fn set_doc(&mut self, doc: Value) -> bool {
        // `setContent` reads `content` from its arguments when present.
        let args = json!({ "content": doc });
        self.view.run("setContent", &args).unwrap_or(false)
    }
}

#[boltffi::export(single_threaded)]
impl NativeEditor {
    /// An editor starting with `content`: a Tiptap JSON document, HTML, or
    /// `""` for an empty document. Sizes are in pixels.
    pub fn new(width: f32, height: f32, density: f32, dark: bool, content: String) -> Self {
        let options = |content: Option<Value>| ViewOptions {
            editor: EditorOptions {
                content,
                platform: KeyPlatform::Other,
                ..Default::default()
            },
            theme: theme(dark),
            width: width / density,
            height: height / density,
            scale: density,
            ..Default::default()
        };
        let mut view = EditorView::new(options(initial_doc(&content)))
            .or_else(|_| EditorView::new(options(None)))
            .expect("an empty document is always valid");
        view.set_padding(Insets {
            top: 24.0,
            right: 20.0,
            bottom: 24.0,
            left: 20.0,
        });
        Self {
            view,
            #[cfg(target_os = "android")]
            shell: Default::default(),
        }
    }

    // --- content and commands (the Tiptap API) ------------------------------

    /// The document as Tiptap JSON.
    pub fn get_json(&self) -> String {
        self.view.editor().get_json().to_string()
    }

    /// The document as Tiptap-style HTML.
    pub fn get_html(&self) -> String {
        openrich_markup::serialize_fragment(self.view.editor().doc().content())
    }

    /// Plain text, blocks separated by `\n`.
    pub fn get_text(&self) -> String {
        self.view.editor().get_text("\n")
    }

    pub fn is_empty(&self) -> bool {
        self.view.editor().is_empty()
    }

    /// Replaces the document with Tiptap JSON; false when it does not fit
    /// the schema.
    pub fn set_json(&mut self, json: String) -> bool {
        serde_json::from_str::<Value>(&json).is_ok_and(|doc| self.set_doc(doc))
    }

    /// Replaces the document with HTML, parsed as a paste would be.
    pub fn set_html(&mut self, html: String) -> bool {
        let schema = self.view.editor().schema().clone();
        let fragment = openrich_markup::parse_fragment(&schema, &html);
        let mut content = fragment_to_json(&fragment);
        if content.as_array().is_none_or(Vec::is_empty) {
            content = json!([{"type": "paragraph"}]);
        }
        self.set_doc(json!({"type": "doc", "content": content}))
    }

    pub fn is_editable(&self) -> bool {
        self.view.editor().is_editable()
    }

    pub fn set_editable(&mut self, editable: bool) {
        self.view.editor_mut().set_editable(editable);
    }

    /// Runs a named command (`toggleBold`, `toggleHeading` with
    /// `{"level": 2}`, …); false when it did not apply or does not exist.
    pub fn run(&mut self, name: String, args_json: String) -> bool {
        self.view.run(&name, &args(&args_json)).unwrap_or(false)
    }

    pub fn can(&mut self, name: String, args_json: String) -> bool {
        self.view
            .can_chain(&[(name, args(&args_json))])
            .unwrap_or(false)
    }

    /// Runs `[{"name", "args"}, …]` as one transaction; true only if every
    /// command applied.
    pub fn run_chain(&mut self, steps_json: String) -> bool {
        steps(&steps_json).is_some_and(|steps| self.view.run_chain(&steps).unwrap_or(false))
    }

    pub fn can_chain(&mut self, steps_json: String) -> bool {
        steps(&steps_json).is_some_and(|steps| self.view.can_chain(&steps).unwrap_or(false))
    }

    /// Whether the mark or node `name` (with `attrs_json`, `{}` for any)
    /// is active at the selection.
    pub fn is_active(&self, name: String, attrs_json: String) -> bool {
        let attrs = match args(&attrs_json) {
            Value::Object(attrs) => attrs,
            _ => Map::new(),
        };
        self.view.editor().is_active(&name, &attrs)
    }

    /// Attributes of the mark or node `name` at the selection, as JSON.
    pub fn get_attributes(&self, name: String) -> String {
        Value::Object(self.view.editor().get_attributes(&name)).to_string()
    }

    /// Changes whenever the document or selection may have changed.
    pub fn revision(&self) -> u64 {
        self.view.revision()
    }

    pub fn set_dark(&mut self, dark: bool) {
        self.view.set_theme(theme(dark));
    }

    pub fn set_focused(&mut self, focused: bool) {
        self.view.set_focused(focused);
    }

    // --- touch and the selection menu ---------------------------------------

    /// A touch event in pixels; `action` is 0 down, 1 move, 2 up, 3 cancel.
    /// Results (keyboard, menu, haptics) come through `take_effects`.
    pub fn touch(&mut self, action: i32, x: f32, y: f32) {
        let scale = self.view.size().2;
        let phase = match action {
            0 => TouchPhase::Down,
            1 => TouchPhase::Move,
            2 => TouchPhase::Up,
            _ => TouchPhase::Cancel,
        };
        self.view.touch(phase, x / scale, y / scale);
    }

    /// Effects since the last call as a JSON array of
    /// `{type: haptic|menu|magnifier|showKeyboard|clipboard|openUrl, …}`.
    pub fn take_effects(&mut self) -> String {
        let scale = self.view.size().2;
        let effects: Vec<Value> = self
            .view
            .take_effects()
            .into_iter()
            .filter_map(|effect| match effect {
                Effect::Haptic(kind) => Some(json!({"type": "haptic", "kind": match kind {
                    HapticKind::LongPress => "longPress",
                    HapticKind::TextHandleMove => "textHandleMove",
                }})),
                Effect::SelectionMenu(menu) => Some(json!({"type": "menu", "menu": menu.map(|m| json!({
                    "rect": [m.rect.x * scale, m.rect.y * scale, m.rect.right() * scale, m.rect.bottom() * scale],
                    "items": m.items.iter().map(|item| menu_item_name(*item)).collect::<Vec<_>>(),
                }))})),
                Effect::Magnifier(at) => Some(json!({"type": "magnifier", "at": at.map(|(x, y)| [x * scale, y * scale])})),
                Effect::ShowKeyboard => Some(json!({"type": "showKeyboard"})),
                Effect::Clipboard(content) => Some(json!({"type": "clipboard", "text": content.text, "html": content.html})),
                Effect::OpenUrl(url) => Some(json!({"type": "openUrl", "url": url})),
                Effect::Redraw | Effect::ImeCursorArea(_) | Effect::Cursor(_) => None,
            })
            .collect();
        Value::Array(effects).to_string()
    }

    /// A command chosen from the selection menu (`cut`, `copy`, `paste`,
    /// `selectAll`). For paste, the clipboard's text and HTML (HTML wins).
    /// Returns `{text, html}` JSON to put on the clipboard, or `""`.
    pub fn menu_action(
        &mut self,
        item: String,
        text: Option<String>,
        html: Option<String>,
    ) -> String {
        let item = match item.as_str() {
            "cut" => MenuItem::Cut,
            "copy" => MenuItem::Copy,
            "paste" => MenuItem::Paste,
            _ => MenuItem::SelectAll,
        };
        self.view
            .menu_action(item, text.as_deref(), html.as_deref())
            .map(|content| json!({"text": content.text, "html": content.html}).to_string())
            .unwrap_or_default()
    }

    /// The system closed the selection menu (back button, a tap elsewhere).
    pub fn menu_dismissed(&mut self) {
        self.view.selection_menu_dismissed();
    }

    // --- keys and the input method ------------------------------------------

    /// A hardware or IME key (`sendKeyEvent`), as a W3C key name.
    pub fn key_down(&mut self, key: String, shift: bool, ctrl: bool, alt: bool) -> bool {
        let event = KeyEvent::new(
            &key,
            Modifiers {
                shift,
                ctrl,
                alt,
                meta: false,
            },
        );
        self.view.key_down(&event)
    }

    /// `commitText`: replaces the composition (or selection) with `text`;
    /// newlines split blocks like Enter.
    pub fn commit_text(&mut self, text: String) {
        let view = &mut self.view;
        for (index, line) in text.split('\n').enumerate() {
            if index > 0 {
                view.key_down(&KeyEvent::new("Enter", Modifiers::default()));
            }
            if view.composition_range().is_some() {
                view.commit_composition(line);
            } else if !line.is_empty() {
                view.insert_text(line);
            }
        }
    }

    pub fn set_composing_text(&mut self, text: String) {
        self.view.set_composition(&text);
    }

    /// `setComposingRegion`, in UTF-16 offsets within the IME block.
    pub fn set_composing_region(&mut self, start: i32, end: i32) {
        self.view
            .ime_set_composing_region(start.max(0) as usize, end.max(0) as usize);
    }

    pub fn finish_composing(&mut self) {
        self.view.ime_finish_composition();
    }

    /// `deleteSurroundingText`, in UTF-16 units.
    pub fn delete_surrounding(&mut self, before: i32, after: i32) {
        self.view
            .ime_delete_surrounding(before.max(0) as usize, after.max(0) as usize);
    }

    /// `setSelection`, in UTF-16 offsets within the IME block.
    pub fn set_selection(&mut self, start: i32, end: i32) {
        self.view
            .ime_set_selection(start.max(0) as usize, end.max(0) as usize);
    }

    /// `replaceText` (API 33): replaces `start..end` of the IME block with
    /// `text`, as keyboards do to undo an autocorrection.
    pub fn replace_text(&mut self, start: i32, end: i32, text: String) {
        self.view
            .ime_replace(start.max(0) as usize, end.max(0) as usize, &text, false);
    }

    /// The IME block as JSON: `{start, text, selection, composition,
    /// caret}`, with the caret in pixels.
    pub fn ime_state(&mut self) -> String {
        let caret = self.view.caret_rect().map(|r| {
            let scale = self.view.size().2;
            [r.x * scale, r.y * scale, r.width * scale, r.height * scale]
        });
        let state = match self.view.ime_context() {
            Some(context) => json!({
                "start": context.start,
                "text": context.text,
                "selection": [context.selection.0, context.selection.1],
                "composition": context.composition.map(|(a, b)| [a, b]),
                "caret": caret,
            }),
            None => {
                json!({"start": -1, "text": "", "selection": [0, 0], "composition": null, "caret": caret})
            }
        };
        state.to_string()
    }

    /// Geometry for `CursorAnchorInfo`, in pixels: the caret line
    /// (`[x, top, baseline, bottom]`) and the bounds of each UTF-16 unit in
    /// `from..to` of the IME block (`null` where not laid out).
    pub fn ime_cursor_info(&mut self, from: i32, to: i32) -> String {
        let view = &mut self.view;
        let scale = view.size().2;
        let caret = view.ime_caret().map(|c| {
            [
                c.x * scale,
                c.top * scale,
                c.baseline * scale,
                c.bottom * scale,
            ]
        });
        let bounds: Vec<Value> = view
            .ime_character_bounds(from.max(0) as usize, to.max(from).max(0) as usize)
            .into_iter()
            .map(|rect| {
                rect.map_or(Value::Null, |r| {
                    json!([
                        r.x * scale,
                        r.y * scale,
                        r.right() * scale,
                        r.bottom() * scale
                    ])
                })
            })
            .collect();
        json!({"caret": caret, "bounds": bounds}).to_string()
    }

    // --- clipboard -----------------------------------------------------------

    /// Copies or cuts the selection; `{text, html}` JSON (empty strings
    /// when nothing is selected).
    pub fn copy(&mut self, cut: bool) -> String {
        let copied = if cut {
            self.view.cut()
        } else {
            self.view.copy()
        };
        match copied {
            Some(content) => json!({"text": content.text, "html": content.html}),
            None => json!({"text": "", "html": ""}),
        }
        .to_string()
    }

    pub fn paste(&mut self, text: String) {
        self.view.paste_text(&text);
    }

    /// Pastes clipboard HTML; false when it held nothing usable.
    pub fn paste_html(&mut self, html: String) -> bool {
        self.view.paste_html(&html)
    }
}
